(()=>{
const rates={QAR:1,USD:0.274725,EUR:0.2345,GBP:0.2045,AED:1.0088,SAR:1.0302,KWD:0.0839,BHD:0.1033,OMR:0.1057,TND:0.812908,MAD:2.63508};
const symbols={QAR:'QAR',USD:'$',EUR:'€',GBP:'£',AED:'AED',SAR:'SAR',KWD:'KWD',BHD:'BHD',OMR:'OMR',TND:'TND',MAD:'MAD'};
let currency=localStorage.getItem('sultana-currency')||'QAR';
if(!rates[currency])currency='QAR';
const removeLanguageBox=()=>{let style=document.getElementById('sultana-language-clean');if(!style){style=document.createElement('style');style.id='sultana-language-clean';style.textContent='.language-switch{border:0!important;outline:0!important;box-shadow:none!important;background:transparent!important;border-radius:0!important;padding:6px 2px!important}';document.head.appendChild(style)}};
const ensureOptions=()=>{document.querySelectorAll('#currency-select').forEach(s=>{if(!s.querySelector('option[value="TND"]'))s.insertAdjacentHTML('beforeend','<option value="TND">🇹🇳 TND</option>');if(!s.querySelector('option[value="MAD"]'))s.insertAdjacentHTML('beforeend','<option value="MAD">🇲🇦 MAD</option>')})};
const fmt=n=>{const v=n*rates[currency];return `${symbols[currency]} ${v.toLocaleString(undefined,{minimumFractionDigits:currency==='QAR'?0:2,maximumFractionDigits:2})}`};
const priceSelectors='.price,.detail-price,#bag-total,.cart-total,.cart-subtotal,.subtotal,.total,[data-price-display],[data-money]';
const captureQar=el=>{if(el.dataset.qar)return;const m=el.textContent.match(/QAR\s*([\d,.]+)/i);if(m)el.dataset.qar=m[1].replace(/,/g,'')};
const convertText=()=>{document.querySelectorAll(priceSelectors).forEach(el=>{captureQar(el);if(el.dataset.qar){const next=fmt(Number(el.dataset.qar));if(el.textContent!==next)el.textContent=next}})};
const installHeader=()=>{const h=document.querySelector('header');if(!h||h.dataset.luxuryHeader)return;h.dataset.luxuryHeader='1';const nav=h.querySelector('nav'),brand=h.querySelector('.brand'),actions=h.querySelector('.header-actions');if(!nav||!brand||!actions)return;const cur=actions.querySelector('#currency-select'),lang=actions.querySelector('.language-switch');const left=document.createElement('div');left.className='luxury-header-left';left.innerHTML='<span class="header-country">Qatar</span><span class="header-sep">|</span>';if(cur)left.appendChild(cur);left.insertAdjacentHTML('beforeend','<span class="header-sep">|</span>');if(lang)left.appendChild(lang);h.appendChild(left);[...nav.children].forEach(el=>el.remove());[['Home','/'],['Perfumes','/shop/?collection=perfume#collection'],['Luxury Spray','/room-sprays/'],['Oud & Bakhoor','/oud-bakhoor/'],['B2B','/b2b/'],['Our Story','/our-story/'],['Contact','/contact/']].forEach(([label,href])=>{const a=document.createElement('a');a.href=href;a.textContent=label;nav.appendChild(a)});let style=document.getElementById('sultana-luxury-header');if(!style){style=document.createElement('style');style.id='sultana-luxury-header';style.textContent=`@media(min-width:851px){header[data-luxury-header]{display:grid!important;grid-template-columns:1fr auto 1fr!important;grid-template-rows:auto auto!important;column-gap:24px!important;row-gap:4px!important;min-height:166px!important;padding:14px 4.5% 0!important;align-items:center!important;background:#fffdfa!important}header[data-luxury-header] .luxury-header-left{grid-column:1;grid-row:1;display:flex;align-items:center;gap:13px;justify-self:start;font-size:11px;white-space:nowrap}header[data-luxury-header] .header-country{font-weight:500}header[data-luxury-header] .header-sep{color:#8c857a}header[data-luxury-header] .luxury-header-left .currency-select{width:auto;max-width:112px;margin:0;padding:6px 2px;font-size:11px}header[data-luxury-header] .luxury-header-left .language-switch{font-size:12px!important}header[data-luxury-header]>.brand{grid-column:2!important;grid-row:1!important;justify-self:center!important;width:88px!important;height:108px!important;margin:0!important}header[data-luxury-header]>.brand img{width:100%!important;height:100%!important;object-fit:contain!important}header[data-luxury-header]>.header-actions{grid-column:3!important;grid-row:1!important;justify-self:end!important;display:flex!important;gap:12px!important}header[data-luxury-header]>.header-actions .currency-select,header[data-luxury-header]>.header-actions .language-switch{display:none!important}header[data-luxury-header]>nav{grid-column:1/-1!important;grid-row:2!important;display:flex!important;justify-content:center!important;align-items:center!important;gap:clamp(22px,3vw,48px)!important;width:100%!important;font-size:11px!important;letter-spacing:.45px!important;padding:2px 0 11px!important;text-transform:uppercase!important}header[data-luxury-header]>nav>a{padding:8px 0!important;white-space:nowrap!important}header[data-luxury-header] .menu-toggle{display:none!important}}@media(max-width:850px){header[data-luxury-header] .luxury-header-left{display:none!important}}`;document.head.appendChild(style)}};
const sync=()=>{removeLanguageBox();ensureOptions();document.querySelectorAll('#currency-select').forEach(s=>s.value=currency);convertText();installHeader()};
document.addEventListener('change',e=>{if(e.target.id==='currency-select'){currency=e.target.value;localStorage.setItem('sultana-currency',currency);sync()}});new MutationObserver(convertText).observe(document.body,{subtree:true,childList:true});document.addEventListener('DOMContentLoaded',sync);window.addEventListener('load',sync);removeLanguageBox();window.SultanaCurrency={formatQAR:fmt,get:()=>currency,refresh:sync};
})();